"""V8.393: one blur-based budget commit path with a preferred 35 percent rate."""
from pathlib import Path
import sys
path=Path(sys.argv[1] if len(sys.argv)>1 else "_site/index.html")
html=path.read_text(encoding="utf-8")
start=html.find('document.addEventListener("beforeinput",(event)=>{\n  const el=event.target;\n  if(!el || !budgetRateRecalcIds.has(el.id)) return;')
end=html.find('if($("budgetAssumptionsToggle") && $("budgetAssumptionsSection")){',start)
if start<0 or end<0:raise SystemExit("Legacy budget recalculation block missing")
html=html[:start]+"// Cashflow values are committed only after the edited field loses focus.\nlet budgetCashflowCommitting=false;\nconst budgetCashflowPending=new Set();\nfunction isBudgetCashflowField(field){\n  return !!field&&(budgetRateIncomeIds.has(field.id)||budgetRateExpenseIds.has(field.id));\n}\nfunction commitBudgetCashflow(field){\n  if(field&&!budgetCashflowPending.delete(field))return;\n  if(budgetCashflowCommitting)return;\n  budgetCashflowCommitting=true;\n  try{\n    budgetRateNeedsInitialValue=false;\n    budgetRateManualSelection=false;\n    localStorage.setItem(\"ff_budget_rateNeedsInitialValue\",\"0\");\n    localStorage.setItem(\"ff_budget_rateManualSelection\",\"0\");\n    localStorage.setItem(\"ff_budget_rateSliderPct\",\"35\");\n    if(field){\n      field.dispatchEvent(new Event(\"input\",{bubbles:true}));\n      field.dispatchEvent(new Event(\"change\",{bubbles:true}));\n    }\n    const updated=budgetModel();\n    const preferredPct=Math.min(35,Math.max(0,updated.maxRatePct||0));\n    localStorage.setItem(\"ff_budget_rateSliderPct\",String(preferredPct));\n    budgetRateSliderSyncing=true;\n    if($(\"budgetSafetyReserve\")) $(\"budgetSafetyReserve\").value=String(Math.round(updated.minimumReserve));\n    budgetRateSliderSyncing=false;\n    renderBudget();\n  }finally{budgetCashflowCommitting=false;}\n}\nfor(const type of [\"input\",\"change\"]){\n  document.addEventListener(type,event=>{\n    const field=event.target;\n    if(budgetCashflowCommitting||!isBudgetCashflowField(field))return;\n    budgetCashflowPending.add(field);\n    event.stopImmediatePropagation();\n    if(document.activeElement!==field)commitBudgetCashflow(field);\n  },true);\n}\ndocument.addEventListener(\"focusout\",event=>{\n  if(isBudgetCashflowField(event.target))commitBudgetCashflow(event.target);\n},true);\ndocument.addEventListener(\"input\",event=>{\n  if(!budgetCashflowCommitting&&budgetFinancingAssumptionIds.has(event.target?.id))commitBudgetCashflow();\n});\nif(document.readyState===\"loading\"){\n  document.addEventListener(\"DOMContentLoaded\",()=>commitBudgetCashflow(),{once:true});\n}else commitBudgetCashflow();\n"+'\n'+html[end:]
for obsolete in ('budgetRateBeforeRecalc=Math.max(0,Number(beforeChange.monthlyRate)||0);','const adjustedRate=budgetRateManualSelection','if(!el || !budgetRateNeedsInitialValue || !budgetRateIncomeIds.has(el.id)) return;'):
 if obsolete in html:raise SystemExit("Legacy budget rule remains: "+obsolete)
path.write_text(html,encoding="utf-8")
print("V8.393 budget updates on field exit; preferred rate 35 percent")
